cat > scraper_browseruse.js <<'NODE'
/*
BrowserUse/Chrome-CDP scraper for tabletop/upcoming projects.
Run in the BrowserUse Node REPL (where `page`, `tabs`, and `workspace` are available),
then run `node build_report.js` in this directory.  The script intentionally checkpoints
raw project data and creator website maps so it can be resumed/updated.

Configuration:
  KS_MAX_PAGES: null = all pages, or a number (the delivered run used 10 because the
                source returned intermittent 429s during the session).
  GF_MAX_PAGES: null = all pages (delivered run used all 25).
*/
const fs = require('fs');
const path = require('path');
const out = typeof workspace !== 'undefined' ? workspace : process.cwd();
const KS_MAX_PAGES = null;
const GF_MAX_PAGES = null;
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function scrapeKickstarterProjects() {
  page = await tabs.open('https://www.kickstarter.com/discover/advanced?state=upcoming&category_id=34&sort=newest&seed=2934951&page=1');
  await sleep(3000);
  async function fetchPage(n) {
    return await page.evaluate(async (n) => {
      const p = new URLSearchParams();
      p.set('seed','2934951'); p.set('sort','newest'); p.set('agg_fields','state,category_id');
      if (n > 1) p.set('page', String(n));
      p.append('category_id[]','34'); p.append('state[]','upcoming');
      const r = await fetch('/discover/advanced.json?' + p.toString(), {headers:{accept:'application/json'}});
      const t = await r.text();
      if (!r.ok) throw new Error(`Kickstarter page ${n}: ${r.status} ${t.slice(0,80)}`);
      return JSON.parse(t);
    }, n);
  }
  const first = await fetchPage(1);
  const perPage = first.projects.length;
  const totalPages = Math.ceil(first.total_hits / perPage);
  const pageLimit = Math.min(KS_MAX_PAGES || totalPages, totalPages);
  const projects = [...first.projects];
  for (let n = 2; n <= pageLimit; n++) {
    const j = await fetchPage(n);
    projects.push(...j.projects);
    if (n % 5 === 0 || n === pageLimit) fs.writeFileSync(path.join(out,'kickstarter_projects_raw.json'), JSON.stringify({meta:{total_hits:first.total_hits,pages_est:totalPages,captured_pages:n},projects},null,2));
    await sleep(1300); // avoid 429s
  }
  fs.writeFileSync(path.join(out,'kickstarter_projects_raw.json'), JSON.stringify({meta:{total_hits:first.total_hits,pages_est:totalPages,captured_pages:pageLimit},projects},null,2));
}

function parseGamefoundComponent(text) {
  const jsonStart = text.indexOf('{"props"');
  let depth=0, inStr=false, esc=false, end=-1;
  for (let i=jsonStart; i<text.length; i++) {
    const ch = text[i];
    if (inStr) { if (esc) esc=false; else if (ch==='\\') esc=true; else if (ch==='"') inStr=false; }
    else { if (ch==='"') inStr=true; else if (ch==='{') depth++; else if (ch==='}' && --depth===0) { end=i+1; break; } }
  }
  return JSON.parse(text.slice(jsonStart,end));
}
async function scrapeGamefoundProjects() {
  page = await tabs.open('https://gamefound.com/en/projects/search?SortType=Newest&ProjectPhaseSearchTypes=Upcoming&Source=HomepageProjectLists');
  await sleep(3000);
  async function fetchPage(idx) {
    const html = await page.evaluate(async (idx) => {
      const r = await fetch('/en/projects/search?SortType=Newest&ProjectPhaseSearchTypes=Upcoming&Source=HomepageProjectLists&PageIndex=' + idx);
      if (!r.ok) throw new Error(`Gamefound page ${idx}: ${r.status}`);
      return await r.text();
    }, idx);
    const m = html.match(/<script>(App\.registerComponent\([^<]*SearchProjectsResults[^<]*)<\/script>/);
    if (!m) throw new Error('Gamefound SearchProjectsResults component not found on page ' + idx);
    return parseGamefoundComponent(m[1]).props.result.projects;
  }
  const first = await fetchPage(0);
  const limit = Math.min(GF_MAX_PAGES || first.totalPageCount, first.totalPageCount);
  const projects = [];
  for (let i=0; i<limit; i++) {
    const p = i===0 ? first : await fetchPage(i);
    projects.push(...p.pagedItems);
    if ((i+1) % 5 === 0 || i+1 === limit) fs.writeFileSync(path.join(out,'gamefound_projects_raw.json'), JSON.stringify({meta:{totalItemCount:first.totalItemCount,totalPageCount:first.totalPageCount,captured_pages:i+1},projects},null,2));
    await sleep(250);
  }
}

async function scrapeKickstarterCreatorWebsites() {
  const raw = JSON.parse(fs.readFileSync(path.join(out,'kickstarter_projects_raw.json'),'utf8'));
  const creators = Array.from(new Map(raw.projects.map(p => [p.creator?.slug || String(p.creator?.id), {slug:p.creator?.slug, id:p.creator?.id, name:p.creator?.name, url:(p.creator?.urls?.web?.user || `https://www.kickstarter.com/profile/${p.creator?.slug}`) + '/about'}])).values());
  page = await tabs.open('https://www.kickstarter.com/'); await sleep(1500);
  const map = fs.existsSync(path.join(out,'kickstarter_creator_websites.json')) ? JSON.parse(fs.readFileSync(path.join(out,'kickstarter_creator_websites.json'),'utf8')) : {};
  for (const c of creators) {
    const key = c.slug || String(c.id); if (map[key]) continue;
    map[key] = await page.evaluate(async (c) => {
      const ac = new AbortController(); const to = setTimeout(() => ac.abort(), 10000);
      try {
        const r = await fetch(c.url, {signal: ac.signal}); const html = await r.text(); clearTimeout(to);
        const doc = new DOMParser().parseFromString(html,'text/html');
        const websites = [...new Set(Array.from(doc.querySelectorAll('a[rel*="nofollow"], a[target="_blank"]')).map(a => a.href).filter(h => /^https?:/i.test(h) && !/kickstarter\.com/i.test(h)).filter(h => !/(facebook\.com\/kickstarter|instagram\.com\/kickstarter|twitter\.com\/kickstarter|youtube\.com\/user\/kickstarter|itunes\.apple\.com|play\.google\.com|thecreativeindependent\.com)/i.test(h)))];
        return {...c, status:r.status, websites};
      } catch(e) { clearTimeout(to); return {...c, status:'error', error:String(e), websites:[]}; }
    }, c);
    fs.writeFileSync(path.join(out,'kickstarter_creator_websites.json'), JSON.stringify(map,null,2));
    await sleep(400);
  }
}

async function scrapeGamefoundCreatorWebsites() {
  const raw = JSON.parse(fs.readFileSync(path.join(out,'gamefound_projects_raw.json'),'utf8'));
  const creators = Array.from(new Map(raw.projects.map(p => [p.creator?.urlName || String(p.creator?.creatorID), {urlName:p.creator?.urlName, creatorID:p.creator?.creatorID, name:p.creator?.name, url:`https://gamefound.com/en/creators/${p.creator?.urlName}`}])).values());
  page = await tabs.open('https://gamefound.com/'); await sleep(1500);
  const map = fs.existsSync(path.join(out,'gamefound_creator_websites.json')) ? JSON.parse(fs.readFileSync(path.join(out,'gamefound_creator_websites.json'),'utf8')) : {};
  for (const c of creators) {
    const key = c.urlName || String(c.creatorID); if (map[key]) continue;
    map[key] = await page.evaluate(async (c) => {
      try {
        const r = await fetch(c.url); const html = await r.text();
        const doc = new DOMParser().parseFromString(html,'text/html');
        const websites = [...new Set(Array.from(doc.querySelectorAll('a[href]')).map(a => a.href).filter(h => /^https?:/i.test(h) && !/gamefound\.com/i.test(h)).filter(h => !/(facebook\.com\/gamefound|instagram\.com\/gamefound|x\.com\/gamefound|youtube\.com\/@gamefound|linkedin\.com\/company\/gamefound|policies\.google\.com)/i.test(h)))];
        return {...c, status:r.status, websites};
      } catch(e) { return {...c, status:'error', error:String(e), websites:[]}; }
    }, c);
    fs.writeFileSync(path.join(out,'gamefound_creator_websites.json'), JSON.stringify(map,null,2));
    await sleep(300);
  }
}

